  DATA.audit = audit;
  function audit(data) {
    var unresolved = [];
    var byLabel = {};
    DATA.ENTRIES.forEach(function (e, i) {
      byLabel[e.label] = (byLabel[e.label] || 0) + 1;
      if (!e.mappingType || !e.target) unresolved.push({ index: i, term: e.term, reason: 'targetなし' });
      if (e.mappingType === 'compound' && !(data && data.COMPOUNDS[e.target])) unresolved.push({ index: i, term: e.term, reason: '化合物IDなし: ' + e.target });
      if (e.mappingType === 'alias' && !(data && data.aliasTarget(e.term))) unresolved.push({ index: i, term: e.term, reason: '別名targetなし' });
      if (e.mappingType === 'family' && !(data && data.familyById(e.target))) unresolved.push({ index: i, term: e.term, reason: 'family IDなし: ' + e.target });
      if (e.mappingType === 'material' && !(data && data.materialById(e.target))) unresolved.push({ index: i, term: e.term, reason: '材料IDなし: ' + e.target });
      if (e.mappingType === 'compound' && e.target === '(未解決)') unresolved.push({ index: i, term: e.term, reason: '化合物未解決' });
    });
    var mandatoryUnresolved = [];
    DATA.MANDATORY.forEach(function (m, i) {
      if (!m.target) mandatoryUnresolved.push({ index: i, term: m.term, reason: 'targetなし' });
      if (m.targetType === 'family' && !(data && data.familyById(m.target))) mandatoryUnresolved.push({ index: i, term: m.term, reason: 'family IDなし: ' + m.target });
      if (m.targetType === 'compound' && !(data && data.COMPOUNDS[m.target])) mandatoryUnresolved.push({ index: i, term: m.term, reason: '化合物IDなし: ' + m.target });
      if (m.targetType === 'material' && !(data && data.materialById(m.target))) mandatoryUnresolved.push({ index: i, term: m.term, reason: '材料IDなし: ' + m.target });
    });
    var trueMissingMissing = DATA.TRUE_MISSING.filter(function (x) { return !(data && data.COMPOUNDS[x.id]); }).map(function (x) { return x.id; });
    var crossUnresolved = DATA.CROSSWALK.filter(function (x) {
      if (!x.target) return true;
      if (data && data.COMPOUNDS[x.target]) return false;
      if (data && data.materialById && data.materialById(x.target)) return false;
      if (data && data.familyById && data.familyById(x.target)) return false;
      return true;
    });
    return {
      total: DATA.ENTRIES.length,
      byLabel: byLabel,
      unresolved: unresolved,
      mandatoryUnresolved: mandatoryUnresolved,
      trueMissingMissing: trueMissingMissing,
      crosswalk: DATA.CROSSWALK.length,
      crosswalkUnresolved: crossUnresolved
    };
  }
